INSERT INTO levels (code, name, cefr, sort_order, duration_weeks, lessons_total, vocab_target, outcome, books) VALUES
('BEG', 'Beginner', 'A1', 1, 12, 36, '500+', 'Oddiy gaplar bilan o''zi va atrofi haqida gapira oladi', 'IELTSBridge Beginner kitobi; Essential Grammar in Use (Red Murphy); 4000 Essential English Words 1'),
('ELE', 'Elementary', 'A2', 2, 12, 36, '+800 (jami ~1300)', 'Kundalik vaziyatlarda erkin muloqot qila oladi', 'IELTSBridge Elementary kitobi; Essential Grammar in Use (Red Murphy); Enterprise 2 + Listening Tests; Essential Idioms — Elementary'),
('INT', 'Intermediate', 'B1', 3, 12, 36, '+1000 (jami ~2300)', 'Fikrini asoslab, ravon suhbat yurita oladi (Pre-Intermediate materiali shu bosqich ichida)', 'IELTSBridge Intermediate kitobi; English Grammar in Use (Blue Murphy); Oxford Word Skills; Essential Idioms — Intermediate'),
('UPP', 'Upper Intermediate', 'B2', 4, 12, 36, '+1200 va collocations (jami ~3500)', 'Murakkab mavzularda erkin va aniq gapira oladi', 'IELTSBridge Upper Intermediate kitobi; English Grammar in Use (Blue Murphy); Betty Azar; 1000 English Collocations'),
('ADV', 'Advanced', 'C1', 5, 12, 36, '+1500, idiomalar va collocations (jami ~5000)', 'Tilni akademik darajada, nozikliklari bilan ishlata oladi', 'IELTSBridge Advanced kitobi; Betty Azar (murakkab bo''limlar); Oxford Word Skills Advanced; CALD4'),
('IEL', 'IELTS', 'Band 6.5-7.5+', 6, 12, 36, '1000+ akademik so''z (AWL)', 'Xalqaro imtihonga to''liq tayyor', 'IELTSBridge IELTS kitobi; Cambridge IELTS 8-9; Cambridge Vocabulary for IELTS; 40 IELTS Reading Tests; 80 Academic Listenings')
ON CONFLICT DO NOTHING;

