-- ================== QOLGAN ISHLAR ==================
-- 1) vocabulary.example_en va audio_ref — keyinchalik to'ldiriladi (majburiy emas).
-- 2) materials.url hozircha lokal nisbiy yo'l (IELTSBridge_Audio/...);
--    backend/CDN chiqqach haqiqiy havolalarga almashtiriladi (kod o'zgarmaydi).
-- 3) Audio treklar sintez ovozda (pilot); jonli diktor yozuvida fayllar
--    almashtiriladi, nomlari va IDlari saqlanadi.


-- Yakuniy tekshiruv: har jadvalda nechta yozuv bor
SELECT (SELECT count(*) FROM levels)      AS bosqichlar,
       (SELECT count(*) FROM units)       AS mavzular,
       (SELECT count(*) FROM lessons)     AS darslar,
       (SELECT count(*) FROM assessments) AS baholash,
       (SELECT count(*) FROM vocabulary)  AS lugat,
       (SELECT count(*) FROM materials)   AS materiallar,
       (SELECT count(*) FROM homework)    AS uy_vazifalari;
